BrandingOptions.CustomCss:
/* 0xbf branding: monochrome palette of exhib and glob (dark values). */
:root {
  --0xbf-bg: oklch(17% 0 0);
  --0xbf-fg: oklch(95% 0 0);
  --0xbf-muted: oklch(70% 0 0);
}
html, body, .backgroundContainer, .skinHeader, .mainDrawer, .dialog, .formDialogHeader, .formDialogFooter {
  background-color: var(--0xbf-bg) !important;
}
/* Logo: header, drawer, login. */
.pageTitleWithDefaultLogo {
  background-image: url("data:image/svg+xml;base64,") !important;
  background-size: contain !important;
  background-position: left center !important;
  width: 2.2em !important;
}
.adminDrawerLogo img, img.imgLogoIcon, .loginPage .loginLogo, .headerLeft img {
  content: url("data:image/svg+xml;base64,") !important;
}
/* Accent: no Jellyfin blue. */
.button-submit:not(.button-flat), .raised.button-submit, .emby-button.button-submit {
  background: var(--0xbf-fg) !important;
  color: var(--0xbf-bg) !important;
}
.emby-checkbox:checked + span + .checkboxOutline {
  background-color: var(--0xbf-fg) !important;
  border-color: var(--0xbf-fg) !important;
}
.emby-input:focus, .emby-textarea:focus, .emby-select-withcolor:focus {
  border-color: var(--0xbf-fg) !important;
}
.itemProgressBarForeground, .mdl-slider-background-lower, .sliderBubble, .playedIndicator, .countIndicator {
  background-color: var(--0xbf-fg) !important;
  color: var(--0xbf-bg) !important;
}
.emby-tab-button-active, .emby-tab-button:focus, a:hover, .button-link {
  color: var(--0xbf-fg) !important;
}
.emby-tab-button-active { border-color: var(--0xbf-fg) !important; }
.headerTabs .emby-tab-button-active::after { background: var(--0xbf-fg) !important; }
/* Jellyfin 12 web (MUI): header logo and accents. */
.MuiButton-startIcon > img {
  content: url("data:image/svg+xml;base64,") !important;
}
.inputLabelFocused, .inputLabel-float.inputLabelFocused {
  color: var(--0xbf-fg) !important;
}
.MuiButton-containedPrimary, .MuiFab-primary {
  background-color: var(--0xbf-fg) !important;
  color: var(--0xbf-bg) !important;
}
.MuiButton-textPrimary, .MuiButton-outlinedPrimary, .Mui-checked, .MuiTab-root.Mui-selected, .MuiListItemButton-root.Mui-selected .MuiListItemIcon-root {
  color: var(--0xbf-fg) !important;
}
.MuiTabs-indicator, .MuiLinearProgress-bar, .MuiSlider-track, .MuiSlider-thumb, .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track {
  background-color: var(--0xbf-fg) !important;
}
.MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline {
  border-color: var(--0xbf-fg) !important;
}
/* Login. The 0xbf sign-in first, Quick Connect under it. The password
   form is hidden on videos.0xbf.ch only (web client login.css). */
.readOnlyContent {
  display: flex !important;
  flex-direction: column;
  max-width: 22em !important;
  margin: 10vh auto 1em !important;
}
.loginDisclaimerContainer { order: -1; margin: 0 0 .5em !important; }
.loginDisclaimer {
  color: var(--0xbf-muted) !important;
  text-align: center;
  line-height: 1.5;
  max-width: none !important;
}
.loginDisclaimer p { margin: .4em 0; }
.oxbf-title {
  color: var(--0xbf-fg);
  font-size: 2.2em;
  font-weight: 600;
  letter-spacing: -.01em;
  margin: 0 0 .9em;
}
.oxbf-signin {
  display: block !important;
  text-align: center;
  text-decoration: none;
  padding: .9em !important;
  margin: 0 0 1.2em !important;
  font-size: 1.05em;
}
.btnQuick { order: 1; }
